result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/hashfarm.js", "content": "#!/usr/bin/env node
'use strict';

/**
 * hashfarm.js — compute sha256 of every file under a directory using a pool
 * of worker_threads. Each file is streamed inside its worker with
 * fs.createReadStream piped through a byte counter into crypto.createHash.
 *
 * Usage:
 *   node hashfarm.js [dir] [--workers N] [--out manifest.json]
 *
 * Output: manifest.json with entries sorted by relative path:
 *   { fileCount, totalBytes, entries: [{ path, hash, bytes }, ...] }
 */

const { isMainThread, parentPort, Worker } = require('node:worker_threads');
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const crypto = require('node:crypto');
const { pipeline } = require('node:stream/promises');
const { Transform } = require('node:stream');

/* ------------------------------ worker side ----------------------------- */

async function workerMain() {
  parentPort.on('message', async (filePath) => {
    try {
      let bytes = 0;
      const byteCounter = new Transform({
        transform(chunk, _enc, cb) {
          bytes += chunk.length;
          cb(null, chunk);
        },
      });
      const hash = crypto.createHash('sha256');
      await pipeline(fs.createReadStream(filePath), byteCounter, hash);
      parentPort.postMessage({
        ok: true,
        path: filePath,
        hash: hash.digest('hex'),
        bytes,
      });
    } catch (err) {
      parentPort.postMessage({ ok: false, path: filePath, error: err.message });
    }
  });
}

/* -------------------------------- main side ----------------------------- */

function parseArgs(argv) {
  const opts = {
    dir: '.',
    workers: Math.max(1, Math.min(os.cpus().length, 8)),
    out: 'manifest.json',
  };
  const positional = [];
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--workers') {
      const n = Number(argv[++i]);
      if (!Number.isInteger(n) || n < 1) {
        throw new Error('--workers must be a positive integer');
      }
      opts.workers = n;
    } else if (a === '--out') {
      opts.out = argv[++i];
    } else if (a === '-h' || a === '--help') {
      console.log('usage: node hashfarm.js [dir] [--workers N] [--out FILE]');
      process.exit(0);
    } else if (a.startsWith('--')) {
      throw new Error(`unknown option: ${a}`);
    } else {
      positional.push(a);
    }
  }
  if (positional.length > 1) throw new Error('too many positional arguments');
  if (positional.length === 1) opts.dir = positional[0];
  return opts;
}

/** Recursively collect all file paths under `dir`, sorted. */
function walk(dir) {
  const files = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...walk(p));
    } else if (entry.isFile()) {
      files.push(p);
    }
  }
  return files.sort();
}

/**
 * Dispatch `files` across a pool of `size` workers; each idle worker gets the
 * next path as soon as it reports back. Resolves with one result per file.
 */
function runPool(files, size) {
  return new Promise((resolve, reject) => {
    const results = [];
    const workers = new Set();
    const idle = [];
    let next = 0;
    let pending = files.length;

    const dispatch = () => {
      while (idle.length > 0 && next < files.length) {
        const w = idle.pop();
        w.postMessage(files[next++]);
      }
    };

    for (let i = 0; i < size; i++) {
      const w = new Worker(__filename);
      workers.add(w);
      w.on('message', (msg) => {
        if (!msg.ok) {
          reject(new Error(`${msg.path}: ${msg.error}`));
          return;
        }
        results.push(msg);
        pending--;
        if (pending === 0) {
          for (const other of workers) other.terminate();
          resolve(results);
          return;
        }
        if (next < files.length) {
          w.postMessage(files[next++]);
        } else {
          // No work left; retire this worker.
          workers.delete(w);
          w.terminate().catch(() => {});
        }
      });
      w.on('error', (err) => {
        reject(err);
        for (const other of workers) other.terminate();
      });
      idle.push(w);
    }

    if (pending === 0) {
      for (const w of workers) w.terminate();
      resolve(results);
      return;
    }
    dispatch();
  });
}

async function main() {
  const opts = parseArgs(process.argv.slice(2));
  const root = path.resolve(opts.dir);
  if (!fs.existsSync(root) || !fs.statSync(root).isDirectory()) {
    console.error(`hashfarm: not a directory: ${root}`);
    process.exit(1);
  }

  const started = process.hrtime.bigint();
  const files = walk(root);
  const size = Math.min(opts.workers, Math.max(1, files.length));
  const results = await runPool(files, size);
  const elapsedMs = Number(process.hrtime.bigint() - started) / 1e6;

  const entries = results
    .map(({ path: abs, hash, bytes }) => ({
      path: path.relative(root, abs).split(path.sep).join('/'),
      hash,
      bytes,
    }))
    .sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));

  const manifest = {
    fileCount: entries.length,
    totalBytes: entries.reduce((sum, e) => sum + e.bytes, 0),
    entries,
  };

  const outPath = path.resolve(opts.out);
  fs.writeFileSync(outPath, JSON.stringify(manifest, null, 2) + '\n');

  console.log(
    `hashfarm: ${entries.length} files, ${manifest.totalBytes} bytes, ` +
      `${size} worker(s) -> ${outPath} in ${elapsedMs.toFixed(1)}ms`
  );
}

if (!isMainThread) {
  workerMain();
} else {
  main().catch((err) => {
    console.error(`hashfarm: ${err.message}`);
    process.exit(1);
  });
}
"})
