'use strict';

/**
 * gen-fixtures.js — deterministic fixture generator.
 *
 * Writes 60 files under a root directory spread across nested subdirectories.
 * Every 9th file is 5 MiB ("several of them 5MB"); the rest are small random
 * sizes. Content is generated from a seeded PRNG so runs are reproducible.
 *
 * Usage: node gen-fixtures.js <rootDir>
 * API:   generateFixtures(rootDir) -> [{ relPath, bytes }]
 */

const fs = require('node:fs');
const path = require('node:path');

function makeRng(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s * 1103515245 + 12345) >>> 0; // LCG, deterministic
    return s / 0x100000000;
  };
}

function generateFixtures(
  rootDir,
  { fileCount = 60, bigSize = 5 * 1024 * 1024, bigEvery = 9 } = {}
) {
  const rng = makeRng(0xc0ffee);
  const dirs = ['', 'sub/a', 'sub/b', 'sub/b/deep', 'sub/c'];
  const made = [];

  fs.rmSync(rootDir, { recursive: true, force: true });
  for (const d of [...new Set(dirs)]) {
    fs.mkdirSync(path.join(rootDir, d), { recursive: true });
  }

  const chunk = Buffer.alloc(64 * 1024);
  for (let i = 0; i < fileCount; i++) {
    const dir = dirs[i % dirs.length];
    const name = `file-${String(i).padStart(2, '0')}.dat`;
    const relPath = path.posix.join(dir, name).replace(/\\/g, '/');
    const targetBytes =
      bigEvery > 0 && i % bigEvery === 0 ? bigSize : 1024 + Math.floor(rng() * 64 * 1024);

    // Fill the reusable chunk deterministically, then write it repeatedly.
    for (let j = 0; j < chunk.length; j += 4) {
      chunk.writeUInt32LE((rng() * 0x100000000) >>> 0, j);
    }
    const fd = fs.openSync(path.join(rootDir, relPath), 'w');
    try {
      let remaining = targetBytes;
      while (remaining > 0) {
        const n = Math.min(remaining, chunk.length);
        fs.writeSync(fd, chunk, 0, n);
        remaining -= n;
      }
    } finally {
      fs.closeSync(fd);
    }
    made.push({ relPath, bytes: targetBytes });
  }
  return made;
}

module.exports = { generateFixtures };

if (require.main === module) {
  const root = process.argv[2];
  if (!root) {
    console.error('usage: node gen-fixtures.js <rootDir>');
    process.exit(1);
  }
  const files = generateFixtures(root);
  const total = files.reduce((s, f) => s + f.bytes, 0);
  const big = files.filter((f) => f.bytes >= 5 * 1024 * 1024).length;
  console.log(`gen-fixtures: ${files.length} files (${big} x 5MiB), ${total} bytes -> ${root}`);
}
"})
