  fs.mkdirSync(path.join(tmpRoot, 'out'), { recursive: true });
  fixturesDir = path.join(tmpRoot, 'fixtures');
  generateFixtures(fixturesDir);
});

test.after(() => {
  fs.rmSync(tmpRoot, { recursive: true, force: true });
});

function runTool({ workers, outName }) {
  const outPath = path.join(tmpRoot, 'out', outName);
  const t0 = process.hrtime.bigint();
  const res = spawnSync(
    process.execPath,
    [HASHFARM, fixturesDir, '--workers', String(workers), '--out', outPath],
