  const elapsedMs = Number(process.hrtime.bigint() - t0) / 1e6;
  assert.strictEqual(res.status, 0, `hashfarm failed (stderr: ${res.stderr})`);
  return { manifest: JSON.parse(fs.readFileSync(outPath, 'utf8')), elapsedMs };
}

/** Serial sha256 of every file under dir — the reference implementation. */
function serialHash(dir) {
  const entries = [];
  const stack = [dir];
  while (stack.length > 0) {
    const d = stack.pop();
    for (const entry of fs.readdirSync(d, { withFileTypes: true })) {
      const p = path.join(d, entry.name);
      if (entry.isDirectory()) stack.push(p);
      else if (entry.isFile()) entries.push(p);
    }
  }
  return entries
    .map((abs) => {
      const buf = fs.readFileSync(abs);
      return {
        path: path.relative(dir, abs).split(path.sep).join('/'),
        hash: crypto.createHash('sha256').update(buf).digest('hex'),
        bytes: buf.length,
      };
